import { useLocale, useTranslations } from "next-intl";
import { formatPercent } from "@/lib/format/percent";
import type { AppLocale } from "@/i18n/routing";

export interface VerdictProps {
  isProfitable: boolean;
  occupancy: number;
  breakEvenOccupancy: number;
}

/**
 * A plain-language verdict generated by a rule (occupancy vs break-even),
 * not by AI (BUILD_PLAN.md Phase 2 scope, previewed here with fixed data).
 */
export function Verdict({ isProfitable, occupancy, breakEvenOccupancy }: VerdictProps) {
  const t = useTranslations("calculator");
  const locale = useLocale() as AppLocale;

  const occupancyText = formatPercent(occupancy, { locale, decimals: 0 });
  const breakEvenText = formatPercent(breakEvenOccupancy, { locale, decimals: 1 });

  return (
    <p
      className={
        isProfitable
          ? "rounded-card bg-profit-foreground p-3 text-sm font-medium text-profit"
          : "rounded-card bg-warning-foreground p-3 text-sm font-medium text-warning"
      }
    >
      {isProfitable
        ? t("verdictProfitable", { occupancy: occupancyText, breakEven: breakEvenText })
        : t("verdictNotProfitable", { occupancy: occupancyText, breakEven: breakEvenText })}
    </p>
  );
}
